{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "청년 기본 조례상 40세의 원칙적 청년 범위 포함 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 청년 기본 조례 제3조제1호는 \"청년\"을 19세 이상 39세 이하의 사람으로 정하므로, 40세는 원칙적인 청년 범위에 포함되지 않는다. 같은 조 제1호 단서는 그 밖의 관계 법령 및 조례에서 따로 규정하는 경우 그 규정에 따르도록 하고 있으나, 질문에서는 의무복무 제대군인 특례나 다른 법령·조례의 별도 연령 규정이 적용되지 않는다고 하였으므로 이 단서는 적용되지 않는다.",
          "b_ids": "청년:제3조제1호, 청년:제3조제1호단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
